    private const STATES=['PENDING','CONFIRMED','CHECKED_IN','COMPLETED','CANCELLED','EXPIRED'];
    public function __construct(private PDO $db,private string $directory){}
    private function query(string $sql,array $args=[]):PDOStatement{$s=$this->db->prepare($sql);$s->execute($args);return $s;}
    private static function uuid(mixed $v):string{if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/iD',$v))throw new HttpError(400,'Mã yêu cầu không hợp lệ.');return strtolower($v);}
    private static function text(mixed $v,int $min,int $max):string{if(!is_string($v)||str_contains($v,"\0"))throw new HttpError(400,'Thông tin đặt phòng không hợp lệ.');$v=preg_replace('/^[\s\x{FEFF}]+|[\s\x{FEFF}]+$/u','',$v);$len=$v===null?-1:strlen(mb_convert_encoding($v,'UTF-16LE','UTF-8'))/2;if($len<$min||$len>$max)throw new HttpError(400,'Kiểm tra tên, điện thoại và ghi chú.');return $v;}
    private function tx(callable $fn):array{$this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();try{if(!$this->query("SELECT id FROM jingo_catalog_locks WHERE id='catalog' FOR UPDATE")->fetchColumn())throw new HttpError(503,'Chưa cài khóa danh mục.');$r=$fn();$this->db->commit();return $r;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
    private function expire():void{$this->query("UPDATE jingo_stay_bookings SET status='EXPIRED',version=version+1 WHERE status='PENDING' AND expires_at<=UTC_TIMESTAMP(6) AND JSON_UNQUOTE(JSON_EXTRACT(data,'$.paymentStatus'))='UNPAID'");}
    private static function input(array $in):array
    {
        $selection=['hotelId','roomId','checkIn','checkOut','rooms','adults','children','voucherCode','locale'];if(array_diff(array_keys($in),[...$selection,'requestId','accessKey','expectedTotal','paymentMethod','accepted','contact']))throw new HttpError(400,'Thông tin đặt phòng không hợp lệ.');$out=StayPricing::selection(array_intersect_key($in,array_flip($selection)));$out['requestId']=self::uuid($in['requestId'] ?? null);if(!is_string($in['accessKey'] ?? null)||!preg_match('/^[a-f0-9]{64}$/D',$in['accessKey'])||!is_int($in['expectedTotal'] ?? null)||$in['expectedTotal']<0||$in['expectedTotal']>15000000000||($in['accepted'] ?? null)!==true)throw new HttpError(400,'Kiểm tra giá và đồng ý điều kiện đặt phòng.');$out['accessKey']=$in['accessKey'];$out['expectedTotal']=$in['expectedTotal'];if(!is_string($in['paymentMethod'] ?? null)||!preg_match('/^(?:CASH|PAY_LATER|MANUAL_[a-zA-Z0-9_-]{1,60})$/D',$in['paymentMethod']))throw new HttpError(400,'Hiện chỉ hỗ trợ phương thức thanh toán thủ công.');$out['paymentMethod']=$in['paymentMethod'];$out['accepted']=true;$c=$in['contact'] ?? null;if(!is_array($c)||array_diff(array_keys($c),['name','phone','email','note'])||!is_string($c['email'] ?? null)||strlen($c['email'])>200||!filter_var($c['email'],FILTER_VALIDATE_EMAIL))throw new HttpError(400,'Email hoặc thông tin liên hệ không hợp lệ.');$contact=['name'=>self::text($c['name'] ?? null,2,120),'phone'=>self::text($c['phone'] ?? null,8,25),'email'=>$c['email'],'note'=>self::text(array_key_exists('note',$c)?$c['note']:'',0,2000)];if(!preg_match('/^\+?[0-9 ()-]{8,25}$/D',$contact['phone']))throw new HttpError(400,'Điện thoại không hợp lệ.');$out['contact']=$contact;return $out;
    }
    public function create(array $input):array
    {
        $in=self::input($input);$hash=hash('sha256',json_encode($in,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_LINE_TERMINATORS|JSON_THROW_ON_ERROR));return $this->tx(function()use($in,$hash){$prior=$this->query('SELECT code,request_hash FROM jingo_stay_bookings WHERE id=?',[$in['requestId']])->fetch(PDO::FETCH_ASSOC);if($prior){if(!hash_equals($prior['request_hash'],$hash))throw new HttpError(409,'Mã yêu cầu đã dùng với nội dung khác.');return ['code'=>$prior['code'],'accessKey'=>$in['accessKey']];}$this->expire();$keys=['hotelId','roomId','checkIn','checkOut','rooms','adults','children','voucherCode','locale'];$selection=array_intersect_key($in,array_flip($keys));$q=(new StayQuotes($this->db))->locked($selection);if($q['total']!==$in['expectedTotal'])throw new HttpError(409,'Giá phòng vừa thay đổi. Kiểm tra lại giá trước khi đặt.');$preference=$q['total']>0?(new ManualMethods($this->db))->select($in['paymentMethod']):null;$p=$q['property'];$r=$q['room'];$en=$in['locale']==='en';$data=$selection+['contact'=>$in['contact'],'paymentMethod'=>$in['paymentMethod'],'paymentStatus'=>$q['total']===0?'PAID':'UNPAID','paidAmount'=>0,'total'=>$q['total'],'subtotal'=>$q['subtotal'],'originalTotal'=>$q['originalTotal'],'voucherDiscount'=>$q['discount'],'voucherCode'=>$in['voucherCode']];if($preference)$data['manualPreference']=$preference;if($q['voucherId']!==null)$data['voucherId']=$q['voucherId'];$data['nights']=array_map(function($n){unset($n['stock'],$n['remaining']);return $n;},$q['nights']);foreach(['hotelName'=>[$p,'name'],'roomName'=>[$r,'name'],'destination'=>[$p,'destination'],'address'=>[$p,'address'],'policy'=>[$p,'policy']] as $key=>[$source,$field])$data[$key]=$en&&($source[$field.'En'] ?? '')!==''?$source[$field.'En']:$source[$field];$data['mapUrl']=$p['mapUrl'];$data['checkInTime']=$p['checkInTime'];$data['checkOutTime']=$p['checkOutTime'];$data['operatorNote']='';$code='JH'.strtoupper(bin2hex(random_bytes(5)));$secret=(new SecretCipher($this->directory))->encrypt($in['accessKey']);$this->query('INSERT INTO jingo_stay_bookings(id,code,hotel_id,room_id,check_in,check_out,rooms,access_hash,secret,request_hash,data,expires_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,NULL)',[$in['requestId'],$code,$in['hotelId'],$in['roomId'],$in['checkIn'],$in['checkOut'],$in['rooms'],hash('sha256',$in['accessKey']),$secret,$hash,json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR)]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),'public','stay.booking.create',$in['requestId']]);StayMail::enqueue($this->db,$in['requestId'],'CREATED',1);(new Notifications($this->db))->enqueue('STAY',$code);return ['code'=>$code,'accessKey'=>$in['accessKey']];});
    }
    public function lookup(array $in):array
    {
        if(count($in)!==2||array_diff(array_keys($in),['code','accessKey'])||!is_string($in['code'] ?? null)||!preg_match('/^JH[A-F0-9]{10}$/D',$in['code'])||!is_string($in['accessKey'] ?? null)||!preg_match('/^[a-f0-9]{64}$/D',$in['accessKey']))throw new HttpError(400,'Mã đơn hoặc khóa tra cứu không hợp lệ.');return $this->tx(function()use($in){$this->expire();$r=$this->query('SELECT code,status,data,version,expires_at,access_hash FROM jingo_stay_bookings WHERE code=?',[$in['code']])->fetch(PDO::FETCH_ASSOC);if(!$r||!hash_equals($r['access_hash'],hash('sha256',$in['accessKey'])))throw new HttpError(404,'Không tìm thấy đơn phòng.');$d=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);unset($d['voucherId'],$d['operatorNote']);return ['code'=>$r['code'],'bookingStatus'=>$r['status'],'paymentStatus'=>$d['paymentStatus'],'expiresAt'=>$r['expires_at'],'total'=>$d['total'],'data'=>$d,'version'=>(int)$r['version']];});
    }
    public function list(array $in):array
    {
        if(array_diff(array_keys($in),['q','status','page'])||isset($in['q'])&&!is_string($in['q'])||isset($in['status'])&&!in_array($in['status'],self::STATES,true)||isset($in['page'])&&(!is_string($in['page'])&&!is_int($in['page'])||!preg_match('/^[1-9][0-9]{0,5}$/D',(string)$in['page'])||(int)$in['page']>100000))throw new HttpError(400,'Bộ lọc đơn phòng không hợp lệ.');$q=self::text($in['q'] ?? '',0,120);return $this->tx(function()use($in,$q){$this->expire();$where=[];$args=[];if(isset($in['status'])){$where[]='status=?';$args[]=$in['status'];}if($q!==''){$where[]="(code LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(data,'$.contact.name')) LIKE ? OR JSON_UNQUOTE(JSON_EXTRACT(data,'$.contact.phone')) LIKE ?)";$needle='%'.str_replace(['%','_','\\'],['','',''],$q).'%';array_push($args,$needle,$needle,$needle);}$sql=$where?' WHERE '.implode(' AND ',$where):'';$total=(int)$this->query('SELECT COUNT(*) FROM jingo_stay_bookings'.$sql,$args)->fetchColumn();$page=min((int)($in['page'] ?? 1),max(1,(int)ceil($total/30)));$offset=($page-1)*30;$rows=$this->query('SELECT id,code,hotel_id,room_id,check_in,check_out,rooms,status,data,expires_at,version,created_at FROM jingo_stay_bookings'.$sql.' ORDER BY created_at DESC,id DESC LIMIT 30 OFFSET '.$offset,$args)->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$r){$r['data']=json_decode($r['data'],true,512,JSON_THROW_ON_ERROR);$r['version']=(int)$r['version'];$r['rooms']=(int)$r['rooms'];}unset($r);return ['data'=>$rows,'total'=>$total,'page'=>$page,'pageSize'=>30];});
    }
    public function collect(string $id,array $in,string $actor):array
    {
        $id=self::uuid($id);
        if(array_diff(array_keys($in),['expectedTotal','method','reference','requestId','verified'])||!is_int($in['expectedTotal'] ?? null)||$in['expectedTotal']<=0||$in['expectedTotal']>15000000000||!in_array($in['method'] ?? null,['CASH','BANK'],true)||($in['verified'] ?? null)!==true)throw new HttpError(400,'Kiểm tra số tiền và xác nhận đã thu.');
        $request=self::uuid($in['requestId'] ?? null);$ref=self::text($in['reference'] ?? '',0,150);$ref=$in['method']==='CASH'?'CASH:STAY:'.$request:mb_strtoupper($ref,'UTF-8');
        if($in['method']==='BANK'&&mb_strlen($ref,'UTF-8')<3)throw new HttpError(400,'Nhập mã giao dịch ngân hàng.');
        try{return $this->tx(function()use($id,$in,$ref,$actor){
            $this->expire();$row=$this->query('SELECT status,data,version FROM jingo_stay_bookings WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$row)throw new HttpError(404,'Không tìm thấy đơn phòng.');$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);
            if($d['paymentStatus']==='PAID'&&($d['paymentReference'] ?? '')===$ref&&($d['paidMethod'] ?? '')===$in['method']&&$d['total']===$in['expectedTotal'])return ['ok'=>true];
            if(in_array($row['status'],['CANCELLED','EXPIRED','COMPLETED'],true)||$d['paymentStatus']!=='UNPAID'||$d['total']!==$in['expectedTotal'])throw new HttpError(409,'Đơn không còn được thu hoặc số tiền đã thay đổi.');
            $this->query("INSERT INTO jingo_payment_references(reference_hash,reference,kind,entity_id,amount) VALUES (?,?,'HOTEL_PAYMENT',?,?)",[hash('sha256',$ref),$ref,$id,$d['total']]);
            $d=array_replace($d,['paymentStatus'=>'PAID','paidAmount'=>$d['total'],'paidAt'=>gmdate('Y-m-d\TH:i:s\Z'),'paymentReference'=>$ref,'paidMethod'=>$in['method']]);
            $this->query('UPDATE jingo_stay_bookings SET data=?,expires_at=NULL,version=version+1 WHERE id=?',[json_encode($d,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$id]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,'stay.pay',$id]);StayMail::enqueue($this->db,$id,'PAID',(int)$row['version']+1);return ['ok'=>true];
        });}catch(PDOException $e){if(($e->errorInfo[1] ?? 0)===1062)throw new HttpError(409,'Mã giao dịch đã được ghi thu.');throw $e;}
    }
    public function activity(string $id):array
    {
        $id=self::uuid($id);return $this->tx(function()use($id){
            if(!$this->query('SELECT id FROM jingo_stay_bookings WHERE id=?',[$id])->fetchColumn())throw new HttpError(404,'Không tìm thấy đơn phòng.');
            $events=$this->query("SELECT id,admin_id,action,created_at FROM jingo_audit WHERE entity_id=? AND action IN ('stay.booking.create','stay.booking.update','stay.booking.note','stay.pay') ORDER BY created_at DESC,id DESC LIMIT 101",[$id])->fetchAll(PDO::FETCH_ASSOC);$more=count($events)>100;$events=array_slice($events,0,100);
            $payments=$this->query("SELECT reference,amount,created_at FROM jingo_payment_references WHERE kind='HOTEL_PAYMENT' AND entity_id=? ORDER BY created_at DESC,reference_hash DESC LIMIT 101",[$id])->fetchAll(PDO::FETCH_ASSOC);$paymentsMore=count($payments)>100;$payments=array_slice($payments,0,100);foreach($payments as &$p)$p['amount']=(int)$p['amount'];unset($p);return ['events'=>$events,'eventsMore'=>$more,'payments'=>$payments,'paymentsMore'=>$paymentsMore];
        });
    }
    public function act(string $id,array $in,string $actor):array
    {
        self::uuid($id);if(array_diff(array_keys($in),['version','status','operatorNote'])||!is_int($in['version'] ?? null)||$in['version']<1||$in['version']>=2147483647||(array_key_exists('status',$in)?!in_array($in['status'],self::STATES,true):!array_key_exists('operatorNote',$in)))throw new HttpError(400,'Trạng thái đơn phòng không hợp lệ.');$note=array_key_exists('operatorNote',$in)?self::text($in['operatorNote'],0,2000):null;return $this->tx(function()use($id,$in,$actor,$note){$this->expire();$row=$this->query('SELECT status,data,version,expires_at FROM jingo_stay_bookings WHERE id=? FOR UPDATE',[$id])->fetch(PDO::FETCH_ASSOC);if(!$row||(int)$row['version']!==$in['version'])throw new HttpError(409,'Đơn phòng vừa thay đổi. Tải lại.');$target=$in['status'] ?? $row['status'];$transitions=['PENDING'=>['CONFIRMED','CANCELLED'],'CONFIRMED'=>['CHECKED_IN','CANCELLED'],'CHECKED_IN'=>['COMPLETED']];if($target!==$row['status']&&!in_array($target,$transitions[$row['status']] ?? [],true))throw new HttpError(409,'Không thể chuyển trạng thái này.');$d=json_decode($row['data'],true,512,JSON_THROW_ON_ERROR);if($target==='CHECKED_IN'&&$d['paymentStatus']!=='PAID')throw new HttpError(409,'Ghi nhận thu tiền trước khi nhận phòng.');if($note!==null)$d['operatorNote']=$note;$this->query('UPDATE jingo_stay_bookings SET status=?,data=?,expires_at=?,version=version+1 WHERE id=?',[$target,json_encode($d,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$target==='CONFIRMED'?null:$row['expires_at'],$id]);$this->query('INSERT INTO jingo_audit(id,admin_id,action,entity_id) VALUES (?,?,?,?)',[bin2hex(random_bytes(16)),$actor,($target===$row['status']?'stay.booking.note':'stay.booking.update'),$id]);if($target!==$row['status'])StayMail::enqueue($this->db,$id,$target,(int)$row['version']+1);return ['ok'=>true];});
    }
